// Aurora curtains: slow-drifting vertical shimmer bands wrapping the helix.
// All per-LED math is fixed-point; phases (TURNS) integrate in update().
uniform float speed : 0.0 .. 3.0 = 0.25;   // drift speed of the curtains
uniform float bands : 1.0 .. 8.0 = 3.0;    // number of curtain bands around
uniform float sat   : 0.0 .. 1.0 = 0.75;   // colour saturation
uniform float gain  : 0.0 .. 2.0 = 1.0;    // brightness

state fixed ph1;   // slow primary drift
state fixed ph2;   // faster counter-drift (sheen)
state fixed ph3;   // vertical shimmer
state fixed k;     // band count
state fixed s;     // saturation
state fixed g;     // gain

void update() {
  fixed dtf = fixed(dt);
  ph1 = fract(ph1 + dtf * fixed(speed) * fixed(0.05));
  ph2 = fract(ph2 + dtf * fixed(speed) * fixed(0.11));
  ph3 = fract(ph3 + dtf * fixed(speed) * fixed(0.23));
  k = fixed(bands);
  s = fixed(sat);
  g = fixed(gain);
}

vec3 shade(Led led) {
  fixed fy = fixed(led.pos.y) * fixed(3.3333);   // 0..1 along the height
  fixed fx = fixed(led.uv.x);                    // 0..1 around the column

  // slow vertical shimmer wave
  fixed w = sin(fy * fixed(6.0) + ph3) * fixed(0.08);

  // curtain phase: wraps around, drifts slowly, sheared by height
  fixed t = fract(fx * k + fy * fixed(0.5) + ph1 + w + ph2 * fy);

  // band profile: bright crest with soft shoulders
  fixed band = t * (fixed(1.0) - t);
  band = band * band * fixed(16.0);              // parabolic crest, 0..1
  fixed v = band * (fixed(0.4) + fixed(0.6) * sin(fy * fixed(9.0) + ph2));

  fixed h = fract(fx * fixed(0.5) + fy * fixed(0.25) + ph1);
  return hsv2rgb(h, s, clamp(v * g, fixed(0.0), fixed(1.0)));
}
